<?php namespace Workspace;
$pid=(int)$project['id'];$rid=(int)$traceRelease['id'];$job=$traceJob;$t=$traceTarget;$args=['project'=>$pid,'id'=>$rid]+($job?['job'=>(int)$job['id']]:[]);$dt=static fn($v)=>$v===null?'—':gmdate('Y-m-d H:i:s',(int)$v).' UTC';
$labels=['observed'=>'Наблюдается','disabled'=>'Отключён','missing'=>'Не найден','offline'=>'Offline','environment_mismatch'=>'Окружение не совпадает','identity_mismatch'=>'Ресурс не совпадает','unavailable'=>'Нет свежего подтверждения','unknown'=>'Неизвестно']; ?>
<p><a href="<?= h(url('releases',['project'=>$pid,'id'=>$rid])) ?>">← Выпуск</a> · <a href="<?= h(url('deployments',['project'=>$pid])) ?>">Развёртывания</a> · <a href="<?= h(url('infrastructure',['project'=>$pid])) ?>">Инфраструктура</a> · <a href="<?= h(url('incidents',['project'=>$pid,'release'=>$rid])) ?>">Инциденты</a></p>
<section class="panel"><h2>След выпуска <?= h($traceRelease['tag']) ?></h2><p>Снимок Workspace: <?= h($dt($traceObservedAt)) ?>. Не проверка доступности приложения и не гарантия отсутствия отказов.</p>
<p>SHA <code><?= h($traceRelease['commit_sha']) ?></code> · <?= h($traceRelease['artifact_name']) ?> · SHA-256 <code><?= h($traceRelease['artifact_sha256']) ?></code></p>
<h3>GitHub</h3><?php if($traceGithubEvidence): ?><p><?= h($traceRepository['full_name']) ?> · Release #<?= (int)$traceGithubEvidence['release']['id'] ?> · Asset #<?= (int)$traceGithubEvidence['artifact']['id'] ?> · CI checks: <?= (int)$traceGithubEvidence['ci_count'] ?> · подтверждение <?= h($dt($traceRelease['confirmed_at'])) ?></p><p><a href="<?= h(url('release_trace',$args+['source'=>'github'])) ?>">Проверить текущий тег и артефакт в GitHub</a> (чтение метаданных, не повторный CI и не скачивание артефакта).</p><?php else: ?><p class="planning-warning">Нет действительного подтверждения выпуска и поколения GitHub.</p><?php endif ?>
<?php if($traceLive&&$traceLive['source']==='github'): ?><p>GitHub: <?= h(match($traceLive['state']){'matched'=>'Тег, выпуск и метаданные артефакта совпадают','not_verified'=>'Доказательства не совпадают','unavailable'=>'Источник недоступен',default=>'Неизвестно'}) ?> · <?= h($dt($traceLive['observed_at'])) ?></p><?php endif ?>
<h3>Развёртывания этого выпуска</h3><?php if($traceJobs): ?><form method="get" class="inline"><input type="hidden" name="p" value="release_trace"><input type="hidden" name="project" value="<?= $pid ?>"><input type="hidden" name="id" value="<?= $rid ?>"><label>Задание<select name="job"><?php foreach($traceJobs as $j): ?><option value="<?= (int)$j['id'] ?>" <?= (int)$j['id']===(int)$job['id']?'selected':'' ?>>#<?= (int)$j['id'] ?> · <?= h($j['kind'].' · '.$j['site_name'].' · '.$j['state']) ?></option><?php endforeach ?><?php if(!in_array((int)$job['id'],array_map('intval',array_column($traceJobs,'id')),true)): ?><option selected value="<?= (int)$job['id'] ?>">#<?= (int)$job['id'] ?> (история)</option><?php endif ?></select></label><button class="secondary">Открыть</button></form><?php if($traceJobsMore): ?><p>Последние 100 заданий; более раннее доступно по прямой ссылке из истории.</p><?php endif ?><?php else: ?><p>Нет развёртываний.</p><?php endif ?></section>
<?php if($job): ?><section class="panel"><h2>Деплой #<?= (int)$job['id'] ?> · <?= h($job['state']) ?></h2><p><?= h($t['kind']) ?> · сайт <?= h($t['site_name']) ?> #<?= (int)$t['site_id'] ?> · aaPanel ID <?= (int)$t['remote_id'] ?> · хост #<?= (int)$t['host_id'] ?></p><p>Начало <?= h($dt($job['started_at'])) ?> · завершение <?= h($dt($job['finished_at'])) ?></p><p>SHA после: <code><?= h($job['result']['after']??'—') ?></code> · digest после: <code><?= h($job['result']['after_digest']??'—') ?></code></p>
<p><?= $traceCurrent?'Последнее управляемое развёртывание подтверждает точный SHA и digest.':($job['artifact_observed']?'Историческое подтверждение SHA и digest, не текущее состояние.':'Нет подтверждённого наблюдения SHA и digest этого задания.') ?> Последнее неотменённое задание сайта: #<?= h((string)($job['latest_id']??'—')) ?>.</p><?php if(!$job['identity_matches']): ?><p class="planning-warning">Привязка или ответственный изменились; текущие данные источников не относятся к этому снимку цели.</p><?php endif ?>
<h3>aaPanel и Servers</h3><?php foreach($traceInventory as $source=>$o): ?><article class="inset"><strong><?= h($source) ?> · <?= h($labels[$o['state']]??$o['state']) ?></strong><p>Наблюдение <?= h($dt($o['observed_at'])) ?> (TTL 15 минут).</p><?php if($o['data']): ?><?php if($source==='aapanel'): ?><p><?= h($o['data']['name']) ?> · <?= h($o['data']['status']) ?></p><p>Домены: <?php foreach($o['data']['domains'] as $domain): ?><?= h($domain['name']) ?>:<?= (int)$domain['port'] ?>; <?php endforeach ?></p><p>Сертификат: <?= h($o['data']['certificate']['expires']??'неизвестно') ?></p><?php else: ?><p><?= h($o['data']['name']) ?> · <?= h($o['data']['status']) ?> · <?= h($o['data']['environment']) ?> · v<?= (int)$o['data']['version'] ?></p><p>Asset UUID: <code><?= h($o['data']['id']) ?></code> · Workspace UUID: <code><?= h($o['data']['workspace_id']) ?></code></p><?php endif ?><?php endif ?></article><?php endforeach ?>
<?php if($job['identity_matches']&&$user['role']==='owner'): ?><form method="post" class="inline"><?php formFields('infra.sync') ?><input type="hidden" name="project_id" value="<?= $pid ?>"><input type="hidden" name="host_id" value="<?= (int)$t['host_id'] ?>"><button class="secondary">Обновить инвентарь обоих источников (MFA)</button></form><?php endif ?>
<?php if($traceService): ?><p><a href="<?= h(url('service_ops',['project'=>$pid,'service'=>$traceService['id']])) ?>">Сервис, SLO и поддержка: <?= h($traceService['name']) ?></a></p><?php endif ?></section>
<section class="panel"><h2>Logs конкретного задания</h2><?php if(!$traceBinding): ?><p>Действующее подключение Logs отсутствует.</p><?php else: ?><p><a href="<?= h(url('release_trace',$args+['source'=>'logs'])) ?>">Запросить события из Logs</a> · <a href="<?= h(url('logs',['project'=>$pid,'release'=>$rid,'environment'=>$t['kind']])) ?>">Общий журнал выпуска</a></p><p>Локальные записи доставки (последние 100, в пределах retention). Квитанция доставки не равна текущей доступности события.</p><?php foreach($traceLogs as $row): ?><p><?= h($dt($row['created_at'])) ?> · <?= h($row['event']) ?> · <?= h($row['state']) ?> · request <code><?= h($row['request_id']) ?></code><?php if($row['remote_event']): ?> · remote <?= h($row['remote_event']) ?><?php endif ?></p><?php endforeach ?><?php if(!$traceLogs): ?><p>Нет сохранённых записей доставки.</p><?php endif ?><?php if($traceLogsMore): ?><p>Локальная история усечена.</p><?php endif ?><?php endif ?>
<?php if($traceLive&&$traceLive['source']==='logs'): ?><h3>Ответ Logs</h3><p><?= h($dt($traceLive['observed_at'])) ?> · <?= $traceLive['state']==='observed'?'Выборка получена':'Источник недоступен' ?></p><?php if($traceLive['state']==='observed'): ?><p>До 50 записей источника за <?= (int)$traceLive['days'] ?> дн., затем фильтрация по заданию, выпуску, хосту и окружению. <?= $traceLive['more']?'Есть дополнительные страницы; выборка неполна.':'' ?></p><?php foreach($traceLive['rows'] as $row): ?><p><?= h($row['timestamp']) ?> UTC · <?= h($row['event']) ?> · <code><?= h($row['request_id']) ?></code> · <?= $row['local_receipt']?'Совпадает с локальной записью':'Нет совпадающей локальной записи' ?></p><?php endforeach ?><?php if(!$traceLive['rows']): ?><p>В полученной выборке нет точных совпадений; это не подтверждает отсутствие ошибок.</p><?php endif ?><?php endif ?><?php endif ?></section>
<section class="panel"><h2>Инциденты</h2><h3>С подтверждённой связью по идентификаторам задания</h3><?php foreach($traceIncidents as $i): ?><p><a href="<?= h(url('incidents',['project'=>$pid,'id'=>$i['id']])) ?>">#<?= (int)$i['id'] ?></a> · <?= h($i['condition_code']) ?> · <?= h($i['state']) ?> · <?= h($dt($i['detected_at'])) ?></p><?php endforeach ?><?php if(!$traceIncidents): ?><p>Не найдено точных совпадений в просмотренных сигналах.</p><?php endif ?><?php if($traceIncidentsMore): ?><p>Список усечён.</p><?php endif ?><h3>Контекст сайта (не доказательство причины выпуска)</h3><?php foreach($traceContextIncidents as $i): ?><p><a href="<?= h(url('incidents',['project'=>$pid,'id'=>$i['id']])) ?>">#<?= (int)$i['id'] ?></a> · <?= h($i['condition_code']) ?> · <?= h($i['state']) ?> · <?= h($dt($i['detected_at'])) ?></p><?php endforeach ?><?php if(!$traceContextIncidents): ?><p>Нет записей в выборке.</p><?php endif ?><?php if($traceContextMore): ?><p>Список усечён.</p><?php endif ?><p>Проверка до 100 карточек каждого вида и 100 последних сигналов каждой карточки. Связь не устанавливает причинность и не закрывает инцидент.</p></section><?php endif ?>
